\t\tignoreInactive = ignoreInactive || s.WordPress.IgnoreInactive
\t}
\tif !ignoreInactive {
\t\treturn r
\t}"""

content = content.replace(old_code, new_code)

with open("models/scanresults.go", "w") as f:
    f.write(content)
