Writes probe as *_test.go with unused testing import; go run rejects filename before assertions and corrected probe replaces it at X023. Component: cat << 'EOF' > /tmp/verify_test.go
package main

import (
	"fmt"
	"io/ioutil"
	"os"
	"path/filepath"
	"reflect"
	"testing"
	"time"

	"github.com/markphelps/flipt/config"
)

func main() {
	// Test 1: default.yml
	defCfg, err := config.Load("./config/testdata/config/default.yml")
	if err != nil {
		panic(err)
	}
	if !reflect.DeepEqual(defCfg, config.Default()) {
		panic(fmt.Sprintf("default.yml != Default(): got %+v, want %+v", defCfg, config.Default()))
	}
